// FORMATTER LAPORAN KEHADIRAN (DATABASE VERSION)

// 1. Ambil Data Absensi
let data;

try {
  data = $input.first().json;
} catch (e) {
  return { json: { text: "⚠️ Data kehadiran tidak ditemukan. Pastikan data tersedia." } };
}

// 2. Ambil Identitas dari node login (CheckIDTelegram)
const user = $('CheckIDTelegram').first().json;

const nama = user['Nama'] || 'Siswa';
const nisn = user['Nisn'] || '-';

// 3. Ambil angka absensi
const s = parseInt(data['Sakit']) || 0;
const i = parseInt(data['Izin']) || 0;
const a = parseInt(data['Alpha']) || 0;

// Jika belum ada catatan di database
const catatan = data['catatan'] || '-';

// Hitung total absen
const total = s + i + a;

// Status kehadiran
let status = "✅ AMAN";
if (total > 5) status = "⚠️ WASPADA (Sering Absen)";
if (total > 10) status = "🚨 BAHAYA (Panggilan Orang Tua)";

// 4. Susun pesan
let pesan = `📅 *LAPORAN KEHADIRAN SISWA*\n`;
pesan += `Nama: ${nama}\n`;
pesan += `NISN: ${nisn}\n`;
pesan += `---------------------------\n\n`;

pesan += `📊 *Rincian Absensi:*\n`;
pesan += `🤒 Sakit  : ${s} hari\n`;
pesan += `✉️ Izin   : ${i} hari\n`;
pesan += `❌ Alpha  : ${a} hari\n`;
pesan += `---------------------------\n`;
pesan += `∑ *TOTAL ABSEN : ${total} HARI*\n`;
pesan += `Status: ${status}\n\n`;

pesan += `📝 *Catatan Wali Kelas:*\n`;
pesan += `"${catatan}"`;

// 5. Output ke Telegram
return {
  json: {
    text: pesan
  }
};

// ==============================
// CODE NODE JADWAL (DATABASE)
// ==============================

// 1. Ambil semua data jadwal
const allJadwal = $input.all().map(i => i.json);

if (!allJadwal.length) {
  return { json: { text: "⚠️ Data jadwal kosong." } };
}

// 2. Ambil data user
const telegramData = $('Telegram Trigger').first().json;
const userData = $('CheckIDTelegram').first().json;

const telegramid = telegramData.message.chat.id;
const namaSiswa = userData.Nama || "Siswa";

// Bersihkan kelas user → "Kelas 5" jadi "5"
const userKelas = String(userData.Kelas)
  .replace(/kelas/i, '')
  .replace(/\s/g, '')
  .trim();

// 3. Filter jadwal berdasarkan kelas
const jadwalKelas = allJadwal.filter(row => {

  const kelasRow = String(row.Kelas || '')
    .replace(/kelas/i, '')
    .replace(/\s/g, '')
    .trim();

  return kelasRow === userKelas;
});

// 4. Urutkan hari
const skorHari = {
  senin:1,
  selasa:2,
  rabu:3,
  kamis:4,
  jumat:5,
  sabtu:6,
  minggu:7
};

jadwalKelas.sort((a, b) => {
  const hariA = (a.Hari || '').toLowerCase().trim();
  const hariB = (b.Hari || '').toLowerCase().trim();
  return (skorHari[hariA] || 99) - (skorHari[hariB] || 99);
});

// 5. Format pesan
let pesan =
`📅 *JADWAL MINGGUAN*
Halo ${namaSiswa} 👋
Kelas ${userKelas}
========================
`;

let lastDay = '';

jadwalKelas.forEach(item => {

  const hari = (item.Hari || '').trim().toUpperCase();

  if (hari !== lastDay) {
    pesan += `\n🔻 *${hari}*\n`;
    lastDay = hari;
  }

  pesan += `📚 ${item.Mapel}\n`;
});

// Jika tidak ditemukan
if (!jadwalKelas.length) {
  pesan = `⚠️ Jadwal kelas ${userKelas} tidak ditemukan.`;
}

// 6. Output ke Telegram
return {
  json: {
    text: pesan,
    telegramid
  }
};

// Ambil pesan dari Telegram Trigger
const msg = $('Telegram Trigger').first().json.message.text;

// Cek format
if (!msg.includes("#")) {
  return { json: { valid: false } };
}

// Pecah Pesan
const parts = msg.split("#");
const nisn = parts[0].trim();
const pass = parts[1].trim();

// Outputkan data bersih untuk dipakai node selanjutnya
return {
  json: {
    valid: true,
    nisn_input: nisn,
    pass_input: pass
  }
};

// --- 1. DATA LOGIN USER ---
const user = $('CheckIDTelegram').first().json;

const namaUser = user.Nama;
const nisnUser = user.Nisn;
const kelasUser = user.Kelas;
const telegramid = user.Telegramid;

// --- 2. AMBIL DATA NILAI ---
const dataNilai = $('Ambil Nilai Akhir').all();

// --- 3. AMBIL ABSENSI ---
let dataAbsensi = [];
try {
  dataAbsensi = $('Ambil Absensi').all();
} catch(e) {}

// --- 4. LABEL MAPEL ---
const mapelLabel = {
  "Pendidikan Agama": "☪️ Agama",
  "PPKN": "🇮🇩 PPKN",
  "Bahasa Indonesia": "🗣️ Bahasa Indonesia",
  "Matematika": "🧮 Matematika",
  "IPAS": "🌍 IPAS",
  "Seni Rupa": "🎨 Seni Rupa",
  "PJOK": "⚽ PJOK",
  "Budaya Dan Sasra Minangkabau": "🏠 Budaya Minangkabau"
};

const pemisah = "\n➤ Nilai : ";
const jarakAntarMapel = "\n\n";

// --- 5. SUSUN NILAI ---
let listNilai = "";

for (const item of dataNilai) {
  const row = item.json;

  if (!row.Nisn || row.Nisn !== nisnUser) continue;

  const labelBaru = mapelLabel[row.Mapel] || row.Mapel;
  listNilai += `*${labelBaru}*${pemisah}${row.Nilai}${jarakAntarMapel}`;
}

// --- 6. AMBIL ABSENSI ---
let sakit = "-", izin = "-", alpha = "-";

if (dataAbsensi.length > 0) {
  const absen = dataAbsensi[0].json;

  sakit = absen.Sakit ?? "-";
  izin = absen.Izin ?? "-";
  alpha = absen.Alpha ?? "-";
}

// --- 7. SUSUN PESAN ---
const laporan = `
🎓 *LAPORAN HASIL BELAJAR*

Nama :
👤 ${namaUser}

Nisn :
🆔 ${nisnUser}

Kelas: ${kelasUser}
---------------------------
📚 *NILAI AKADEMIK*

${listNilai.trim()}
---------------------------
📅 *KEHADIRAN*

😷 Sakit : ${sakit}
✉️ Izin  : ${izin}
❌ Alpha : ${alpha}

_Tetap semangat belajar!_ ✨
`;

return [{
  json: {
    nisn: nisnUser,
    nama: namaUser,
    message: laporan.trim(),
    telegramid
  }
}];

// --- 1. AMBIL DATA ---
const dataNilai = $('Nilai Formatif').all();
const dataTP = $('TujuanPembelajaran').all();
let telegramid = $('CheckIDTelegram').first().json.Telegramid;

// --- 2. MAPING NAMA MAPEL ---
const mapelConfig = {
  agama: "Pendidikan Agama",
  ppkn: "PPKN",
  bindo: "Bahasa Indonesia",
  mtk: "MATEMATIKA",
  ipas: "IPAS",
  seni: "Seni Rupa",
  pjok: "PJOK",
  bsm: "BSM"
};

// --- 3. BUAT MAP TUJUAN PEMBELAJARAN ---
const tpMap = {};

for (const item of dataTP) {
  const row = item.json;

  const mapel = row.Mapel;
  const tp = parseInt(row.Tp);
  const desk = row.Deskripsi;

  if (!tpMap[mapel]) tpMap[mapel] = {};
  tpMap[mapel][tp] = desk;
}

// --- 4. KELOMPOKKAN NILAI PER MAPEL ---
const nilaiMap = {};
let nisnSiswa = "-";
let namaSiswa = "Siswa";

for (const item of dataNilai) {
  const row = item.json;

  nisnSiswa = row.Nisn || nisnSiswa;

  const mapelKey = row.Mapel.toLowerCase();
  const tp = parseInt(row.Tp);
  const nilai = row.Nilai;

  if (!nilaiMap[mapelKey]) nilaiMap[mapelKey] = [];
  nilaiMap[mapelKey].push({ tp, nilai });
}

// --- 5. SUSUN LAPORAN ---
let laporanFull = "";

for (const [prefix, namaMapel] of Object.entries(mapelConfig)) {

  const dataMapel = nilaiMap[prefix];
  if (!dataMapel) continue;

  dataMapel.sort((a, b) => a.tp - b.tp);

  let buffer = "";

  for (const item of dataMapel) {

    let deskripsi = "-";

    if (tpMap[namaMapel] && tpMap[namaMapel][item.tp]) {
      deskripsi = tpMap[namaMapel][item.tp];
    }

    buffer +=
      `Tp ${item.tp} : ${deskripsi}\n➤ Nilai : ${item.nilai}\n\n`;
  }

  laporanFull +=
    `📚 *${namaMapel}*\n------------------\n${buffer}`;
}

if (!laporanFull) {
  laporanFull = "Belum ada data nilai formatif.";
}

const finalMessage = `
📝 *LAPORAN FORMATIF*
🆔 NISN : ${nisnSiswa}
========================

${laporanFull.trim()}

_Terus tingkatkan capaian belajarmu!_ ✨
`;

const MAX_LENGTH = 4000;
const pesanFinal = finalMessage.trim();

const results = [];

for (let i = 0; i < pesanFinal.length; i += MAX_LENGTH) {
  results.push({
    json: {
      nisn: nisnSiswa,
      message: pesanFinal.substring(i, i + MAX_LENGTH),
      telegramid
    }
  });
}

return results;

// --- CONFIG NAMA NODE (SAMAKAN DENGAN WORKFLOW) ---
const namaNodeNilai = 'Ambil Nilai Akhir Ai ';
const namaNodeRata  = 'Rata Rata 1';
const namaNodeAbsen = 'Absensi Ai ';

let debugLog = [];

let dataNilai = [];
let dataRata2 = [];
let dataAbsen = {};

// --- AMBIL NILAI SISWA ---
try {
  dataNilai = $(namaNodeNilai).all().map(i => i.json);
  if (!dataNilai.length) throw new Error("Output kosong");
} catch(e) {
  debugLog.push("❌ ERROR NILAI");
}

// --- AMBIL RATA-RATA ---
try {
  dataRata2 = $(namaNodeRata).all().map(i => i.json);
  if (!dataRata2.length) throw new Error("Output kosong");
} catch(e) {
  debugLog.push("❌ ERROR RATA-RATA");
}

// --- AMBIL ABSENSI ---
try {
  dataAbsen = $(namaNodeAbsen).first().json;
} catch(e) {
  debugLog.push("❌ ERROR ABSENSI");
}

// --- JIKA ERROR ---
if (debugLog.length > 0) {
  return {
    json: {
      status: "GAGAL",
      laporan_error: debugLog.join(" | ")
    }
  };
}

// --- DATA LOGIN ---
const login = $('CheckIDTelegram').first().json;
const nama = login.Nama;
const nisn = login.Nisn;

// --- GABUNG NILAI ---
const nilaiMap = {};
dataNilai.forEach(row => {
  nilaiMap[row.Mapel] = row.Nilai;
});

// --- GABUNG RATA-RATA ---
const rataMap = {};
dataRata2.forEach(row => {
  rataMap[row.Mapel] = row.RataRata || row.Nilai || 0;
});

// --- SUSUN PESAN ---
let pesan = `📝 *LAPORAN HASIL BELAJAR*\n`;
pesan += `👤 Nama: ${nama}\n`;
pesan += `🆔 NISN: ${nisn}\n`;
pesan += `------------------------\n`;

Object.keys(nilaiMap).forEach(mapel => {

  const nilaiSiswa = nilaiMap[mapel] || 0;
  const nilaiRata = rataMap[mapel] || 0;

  let icon = '';
  if (nilaiSiswa > nilaiRata) icon = '✅';
  if (nilaiSiswa < nilaiRata) icon = '⚠️';

  pesan += `📚 *${mapel}*: ${nilaiSiswa} _(Avg: ${nilaiRata})_ ${icon}\n`;
});

pesan += `------------------------\n`;
pesan += `📅 *KEHADIRAN*\n`;
pesan += `Sakit: ${dataAbsen.Sakit || 0} | `;
pesan += `Izin: ${dataAbsen.Izin || 0} | `;
pesan += `Alpha: ${dataAbsen.Alpha || 0}\n`;

return {
  json: {
    text_laporan: pesan,
    chat_id: $('Telegram Trigger').first().json.message.chat.id
  }
};

